const triggerData = $('When Executed by Another Workflow').first().json;
const llmRaw      = $('Message a model').first().json;
const validRows   = $input.all();
const validSet    = new Set(validRows.map(r => r.json.chunk_id));

// Extract real OpenAI JSON regardless of n8n node version wrapper
let candidate = llmRaw.message?.content
  ?? llmRaw.content
  ?? llmRaw.text
  ?? (Array.isArray(llmRaw.output) ? llmRaw.output.at(0)?.content?.at(0)?.text : null)
  ?? llmRaw;

let judgeData = {};
if (typeof candidate === 'string') {
  const cleaned = candidate.replace(/^```json\s*/i, "").replace(/```$/i, "").trim();
  try { judgeData = JSON.parse(cleaned); } catch (e) { judgeData = {}; }
} else if (candidate && typeof candidate === 'object') {
  judgeData = candidate;
}

let groundedness  = Number(judgeData.groundedness_score ?? 8.0);
let completeness  = Number(judgeData.completeness_score ?? 8.0);
let consistency   = Number(judgeData.consistency_score ?? 8.0);
let actionability = Number(judgeData.actionability_score ?? 8.0);
const findings    = Array.isArray(judgeData.critic_findings) ? [...judgeData.critic_findings] : [];

// 1. Deterministic UUID Citation Verification
const uuidRegex = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;
const citedIds  = (JSON.stringify(triggerData.artifacts || {}).match(uuidRegex)) || [];
const fakeIds   = [...new Set(citedIds.filter(id => !validSet.has(id.toLowerCase())))];

if (fakeIds.length > 0 && validSet.size > 0) {
  groundedness = Math.max(0, groundedness - 2.0);
  findings.push({
    severity: "CRITICAL",
    target_agent: "solution_architect",
    issue: `Unverified KB chunk citations detected: ${fakeIds.join(", ")}`,
    repair_instruction: "Replace unverified UUIDs with exact CHUNK_ID values returned by PgVector KB Retriever."
  });
}

// 2. Deterministic Requirement Coverage Check
const reqs    = Array.isArray(triggerData.requirements) ? triggerData.requirements : [];
const planCov = triggerData.artifacts?.engineering_plan?.all_covered_requirements || [];
const archCov = triggerData.artifacts?.solution_architect?.all_covered_requirements || [];
const missingReqs = reqs
  .map(r => r.req_id || r.id)
  .filter(id => id && (!planCov.includes(id) || !archCov.includes(id)));

if (missingReqs.length > 0 || planCov.length === 0 || archCov.length === 0) {
  completeness = Math.max(0, completeness - 3.5);
  const missingLabel = missingReqs.length > 0 ? missingReqs.join(", ") : "ALL_BRD_REQUIREMENTS (empty coverage array)";
  findings.push({
    severity: "CRITICAL",
    target_agent: "solution_architect",
    issue: `Missing requirement coverage for: ${missingLabel}`,
    repair_instruction: `Explicitly map all BRD requirements in engineering_plan.all_covered_requirements and solution_architect.all_covered_requirements.`
  });
}

// 3. Deterministic Ambiguity / Feasibility Escalation Check (triggers AMBER -> HITL review)
const artifactStr  = JSON.stringify(triggerData.artifacts || {}).toLowerCase();
const reqsHaveAmbiguity = reqs.some(r => r.ambiguity_flag === true);
const hasAmbiguity = reqsHaveAmbiguity || artifactStr.includes('"ambiguity_flag":true') || artifactStr.includes('"ambiguity_flag": true');

const hasConflict  = /unrealistic|infeasible|1 week|zero budget|conflict/i.test(triggerData.brd_text || "");

if (hasAmbiguity || hasConflict) {
  completeness  = Math.max(0, completeness - 1.5);
  actionability = Math.max(0, actionability - 1.5);
  findings.push({
    severity: "MAJOR",
    target_agent: "human_reviewer",
    issue: hasConflict
      ? "Conflicting or unrealistic delivery constraints detected (requires EM & customer trade-off sign-off)."
      : "Unstated NFR metrics / ambiguities detected (requires customer clarification before release).",
    repair_instruction: "Escalate to Engineering Manager in HITL console."
  });
}

// Weighted Overall Score: Groundedness 30%, Completeness 30%, Consistency 25%, Actionability 15%
const overall = Number((
  groundedness  * 0.30 +
  completeness  * 0.30 +
  consistency   * 0.25 +
  actionability * 0.15
).toFixed(2));

const hasCritical = findings.some(f => f.severity === "CRITICAL");
let badge = "GREEN";
if (overall < 6.0) {
  badge = "RED";
} else if (overall < 8.0 || hasCritical) {
  badge = "AMBER";
}

const revisionNeeded = badge !== "GREEN";

return [{
  json: {
    groundedness_score: Number(groundedness.toFixed(2)),
    completeness_score: Number(completeness.toFixed(2)),
    consistency_score: Number(consistency.toFixed(2)),
    actionability_score: Number(actionability.toFixed(2)),
    overall_score: overall,
    badge,
    revision_needed: revisionNeeded,
    critic_findings: findings
  }
}];
